# THis script is used to validate the SQL query generated by the Open AI

def reconstruct_query(parsed, valid_columns):
    """Reconstruct the SQL statement focusing only on the SELECT part,
    leaving the rest of the query exactly as it was."""
    # Build the new SELECT part with valid columns
    modified_select = f"SELECT {', '.join(valid_columns)}"
    
    # Find the position where the FROM keyword or further appears and capture everything after it
    rest_of_query = ""
    from_found = False
    for token in parsed.tokens:
        if from_found:  # Once 'FROM' is found, concatenate the rest of the tokens as they are
            rest_of_query += str(token)
        elif token.ttype is Keyword and token.value.upper() == 'FROM':
            # Detect the 'FROM' keyword to start capturing the rest of the query
            from_found = True
            # Include the 'FROM' part in the rest_of_query as we build the SELECT manually
            rest_of_query += " " + str(token)

    return modified_select + rest_of_query

def remove_invalid_col(query, invalid_columns): 
    print_colored(f"QUERY: {query}", "RED")   
    #print(f"Invalid columns: {invalid_columns}")
    parsed = sqlparse.parse(query)[0]

    # Get the SELECT identifier list token from the parsed SQL
    identifier_list = None
    for token in parsed.tokens:
        if isinstance(token, sqlparse.sql.IdentifierList):
            identifier_list = token
            break
    
    valid_columns = []
    print_colored(f"Identifier list: {identifier_list}", "CYAN")
    # Iterate over each identifier

    if identifier_list is None:
        print_colored(f"Identifier list: IS NONE", "RED")
        return query
    for ident in identifier_list.get_identifiers():
        print(f"ident: {ident}")

        # Check if the token is a Keyword and not in invalid_columns
        if ident.ttype is Keyword:
            if ident.value not in invalid_columns:
                #print("HERE")
                #print(ident.value)
                valid_columns.append(ident.value)
        else:
            # Safely get the real name of the identifier
            column_name = ident.get_real_name() if hasattr(ident, 'get_real_name') else ident.get_name()
            
            # Check if the column name is not in invalid_columns
            if column_name not in invalid_columns:
                valid_columns.append(column_name)
    
    new_sql_query = reconstruct_query(parsed, valid_columns)
    return new_sql_query

def retrieval_query(query): 
    # THis funciton checks if the squery is only a rettrieval query
    # If the query is attempting to INSERT, UPDATE, DELETE, or CREATE or anything else it will return False

    # Check if the query is non-empty
    if not query.strip():
        print("Empty SQL query.")
        return False
    
    # Parse the SQL query
    parsed = sqlparse.parse(query)
    
    # Check if parsing was successful
    if not parsed:
        print("Error parsing the SQL query.")
        return False

    first_statement = parsed[0]

    # Check if any of the tokens are a DML statement other than SELECT
    for token in first_statement.tokens:
        if token.ttype is sqlparse.tokens.DML and token.value.upper() not in ['SELECT']:
            return False
    return True


    
def create_table2columns_dict2(schema_path):
    with open(schema_path, 'r') as file:
        document_text = file.read()

    # Parse the document into schema
    schema = {}
    current_table = None

    for line in document_text.split('\n'):
        # Check for a table header
        if line.startswith('## Table `'):
            current_table = line.split('`')[1]
            schema[current_table] = []
        elif '|' in line and not line.strip().startswith('| ------------'):
            parts = line.split('|')
            if len(parts) > 1:
                column_name = parts[1].strip()
                if column_name not in ["Column Name", "Data Type"]:  # Skip header and divider lines
                    schema[current_table].append(column_name)

    return schema




def extract_sql_tokens(sql_query):
    # Parse the SQL query
    parsed = sqlparse.parse(sql_query)[0]

    # Extract SELECT and FROM tokens
    select_seen = from_seen = False
    columns = []
    table = None

    for token in parsed.tokens:
        
        if token.ttype is DML and token.value.upper() == 'SELECT':
            select_seen = True
        elif select_seen and not from_seen and token.ttype is Keyword and token.value.upper() == 'FROM':
            from_seen = True
        elif select_seen and not from_seen:
            if isinstance(token, IdentifierList):
                
                for identifier in token.get_identifiers():
                    
                    if identifier.ttype is Keyword: # This is for the specific case when a column is named the same as a SQL KEYWORD for example position
                        #append the keyworkd as a column name
                        
                        columns.append(identifier.value)
                    else:
                        columns.append(identifier.get_name())
            elif isinstance(token, Identifier):
                columns.append(token.get_name()) #get name is for the alias name and get_real_name is for the column name of the alias
        elif from_seen and isinstance(token, Identifier):
            table = token.get_name()
            break

    # Get Aliases if present in the query:
    aliases = get_alias(sql_query)


    tokens = {'table': table, 'columns': columns, 'alias': aliases}
    return tokens

