def validate_alias(sql_tokens,schema):
    Valid_alias = True
    message = ""
    table = sql_tokens['table']
    # columns = sql_tokens['columns']
    aliases = sql_tokens['alias']
    # print("VERIFY ALIAS")
    # print(aliases)
    for alias in aliases:
        # print(alias)
        # print(alias['column_name'])
        # print(schema[table])
        if alias['column_name'] not in schema[table]:
            message = f"Invalid SQL: The column '{alias['column_name']}' is not in the table '{table}'."
            Valid_alias = False
            return [Valid_alias, message]
        else:
            alias_name = alias['alias_name']
            message = f"The SQL Alias is correct regarding table '{table}', column name '{alias['column_name']}' with alias_name '{alias_name}'."
            
            return [Valid_alias, message]

def has_relevant_columns(sql_tokens, invalid_columns):
    """
    Determines if there are relevant columns in the SQL token structure after excluding invalid columns 
    and columns with identifiers or names. It returns True if non-excluded, relevant columns exist, otherwise False.
    """
    # Extract the list of columns from the sql_tokens dictionary
    columns = sql_tokens.get('columns', [])
    
    # Filter columns to exclude invalid columns and columns containing '_id' or '_name'
    valid_columns = [col for col in columns if col not in invalid_columns and '_id' not in col and '_name' not in col]

    # Return True if there are any valid columns left, False otherwise
    return len(valid_columns) > 0
def verify_sql_query(sql_query, sql_tokens, schema):
    

    Valid_query = True
    message = ""
    table = sql_tokens['table']
    columns = sql_tokens['columns']
    modified_sql_query = None
    # VERIFY ALIAS IS VALID OR NOT

    # CHECK SCHEMA IS CORRECTLY LOADED
    #Schema test
    test_table = 'vm_agg_season_player_opta'
    test_table_columns = schema.get(test_table, [])
    if len(test_table_columns) != 565:
        print_colored_full_line("ERROR", "RED")
        print_colored("ERROR",'RED')
        print_colored_full_line("ERROR", "RED")


    

    if sql_tokens['alias']: # If there is an alias in the query
        valid_alias_check = validate_alias(sql_tokens,schema) #This checks if the alias that was created in the query is valid or not

        if not valid_alias_check[0]: 
            return valid_alias_check[1]
        else:
            alias_name = (sql_tokens['alias'][0]['alias_name'])
            column_name = (sql_tokens['alias'][0]['column_name'])
            # Replace the value in columns that is like alias_name with the value column_name
            
            columns = [col if col != alias_name else column_name for col in columns]

    if table not in schema:
        message = f"Invalid SQL: The table '{table}' is not in the schema."
        Valid_query = False
        return [Valid_query, message]
        
    # Validate columns against schema
    table_columns = schema.get(table, [])
    invalid_columns = [col for col in columns if col not in table_columns and col != '*']



    if invalid_columns:
        print_colored(f"INVALID COLUMNS: {invalid_columns} ", "CYAN")
        
        if has_relevant_columns(sql_tokens, invalid_columns):
        
            message = f"Invalid SQL: These columns are not in the table '{table}': {', '.join(invalid_columns)}"
            
            modified_sql_query = remove_invalid_col(sql_query, invalid_columns)
            message = f"remove_invalid_cols: {invalid_columns}"

            if modified_sql_query == sql_query:
                message = f"Invalid SQL: {message} The invalid columns could not be removed from the SQL query."
                Valid_query = False
            return [Valid_query, message, modified_sql_query]
        
        else:
            
            message = f'Invalid SQL: QUERY REJECTED, Invalid Column: {invalid_columns} and no Relevant Columns in the query.'
            print_colored(message, "RED")
            Valid_query = False
            return [Valid_query, message, sql_query]

    message = "The SQL query is correct regarding table and columns."
    return [Valid_query, message, modified_sql_query]


def add_info_to_query(query , schema):
    sql_tokens =  extract_sql_tokens(query) # this extracts the table and columns from the sql query
    table = sql_tokens['table']
    columns = schema[table]
    # Define a list of aggregate functions
    aggregate_functions = ["COUNT", "SUM", "AVG", "MAX", "MIN", "GROUP_CONCAT", "STRING_AGG"]
    
    # Regex to detect if any aggregate function is used
    aggregate_regex = r"\b(" + "|".join(aggregate_functions) + r")\b"
    # Check if the query contains any aggregate functions
    if re.search(aggregate_regex, query, re.IGNORECASE):
        print("Query contains aggregate functions.")
        return query  # Return the original query
    
    # Get columns to add from the schema dictionary
    table_schema = {table: columns}

    id_columns = ['player_id', 'team_id', 'match_id', 'season_id'] # predetermined ID columns

    id_columns = [col for col in table_schema[table] if col in id_columns] # Id columns inside the table used in the query
    if id_columns:
    # Find the current SELECT clause and capture it
        select_clause_search = re.search(r"SELECT (.*?) FROM", query, re.IGNORECASE)
        
        if select_clause_search:
            current_columns = select_clause_search.group(1).strip()
            #print("Current columns:", current_columns)  
            # Prepare new SELECT clause with additional ID columns
            if current_columns != '*':  # Check if current selection is not a wildcard
                new_columns = ', '.join([current_columns] + id_columns)
                new_select_clause = f"SELECT {new_columns}"
                # Replace the original SELECT clause with the new one
                modified_query = re.sub(r"SELECT .*? FROM", f"{new_select_clause} FROM", query, 1, re.IGNORECASE)
                return modified_query
    else:
        print("No suitable '_id' columns found in the schema.")
    return query  # Return the original or modified query
    
