def validate_sql_query(sql_query,schema):
    print_colored(f"SQL QUERY BEFORE VALIDATION: ", "BACKGROUND_CYAN")
    print_colored(f"{sql_query}", "CYAN")

    

    query_status = retrieval_query(sql_query) # Returns True if Query is a retrieval query, return false if not
    if query_status == False:
        return [query_status, "Invalid SQL: The query is not a retrieval query."]
    

    sql_tokens =  extract_sql_tokens(sql_query) # this extracts the table and columns from the sql query

    print("sql_tokens:",sql_tokens)
    
    query_status = verify_sql_query(sql_query, sql_tokens, schema) # Returns True if Query is valid, return false if not


    return query_status


